/* Generated by scripts/build-fallback.php — edit resources/js/pos-till.js instead. */
/*
|------------------------------------------------------------------------------
| The till — floor and bill
|------------------------------------------------------------------------------
| Everything here is a convenience over a screen that already works without it.
| The quick actions are real links, the quantity steppers are submit buttons
| carrying a step, the three dialogs are opened by a link to their own id and
| shown by CSS `:target`, and the settle panels are three separate forms. With
| this file missing the till is slower and a little clumsier — a bill can still
| be printed, settled, comped or cancelled, which is the only acceptable way
| for the machine that runs the restaurant to fail.
|
| Two things genuinely need a script and are worth the file on their own:
|
|   1. The running clocks. The server writes the moment a table was opened as
|      an epoch; the browser counts from it. That keeps the number moving
|      between page loads, and keeps it right on a till whose own clock is
|      wrong, because nothing here reads the local time — only the difference
|      between two of its own readings and a server-stamped start.
|
|   2. The action rail opening on a tap. Hover does not exist on the
|      touchscreen by the kitchen door.
*/

(function () {
    'use strict';

    var all = function (sel, root) {
        return Array.prototype.slice.call((root || document).querySelectorAll(sel));
    };

    /* ───────────────────────────────────────────────────────── dialogs ── */

    function closeModal(modal) {
        modal.classList.remove('is-open');
        document.body.style.overflow = '';

        /*
         * The dialogs are also openable by URL (`#settle`), and CSS `:target`
         * keeps one open for as long as the hash names it. So closing has to
         * take the hash off as well, or the Close button appears to do nothing.
         * replaceState rather than assigning location.hash: this should not
         * leave a step in the history for Back to walk into.
         */
        if (modal.id && location.hash === '#' + modal.id) {
            history.replaceState(null, '', location.pathname + location.search);
        }
    }

    function openModal(name) {
        var modal = document.querySelector('[data-modal="' + name + '"]');
        if (!modal) return null;

        modal.classList.add('is-open');
        document.body.style.overflow = 'hidden';

        return modal;
    }

    all('[data-modal]').forEach(function (modal) {
        all('[data-modal-close]', modal).forEach(function (button) {
            button.addEventListener('click', function (event) {
                event.preventDefault();
                closeModal(modal);
            });
        });

        modal.addEventListener('click', function (event) {
            if (event.target === modal) closeModal(modal);
        });
    });

    /* ──────────────────────────────────────────────────── the clocks ── */

    /*
     * A table open longer than this is worth a glance, and longer than the
     * second one is worth walking over to. They are house-keeping hints, not
     * alarms — nothing is blocked, the tile just stops looking calm.
     */
    var WARM_MINUTES = 90;
    var HOT_MINUTES = 150;

    /** "now" / "12m" / "1h 12m" — as much precision as the number deserves. */
    function spell(seconds) {
        if (seconds < 60) return 'now';

        var minutes = Math.floor(seconds / 60);

        if (minutes < 60) return minutes + 'm';

        return Math.floor(minutes / 60) + 'h ' + (minutes % 60) + 'm';
    }

    function tickClocks() {
        var now = Math.floor(Date.now() / 1000);

        all('[data-since]').forEach(function (tile) {
            var since = parseInt(tile.getAttribute('data-since'), 10);
            var value = tile.querySelector('[data-clock-value]');

            if (!since || !value) return;

            /*
             * A till whose clock is behind the server's would otherwise show a
             * negative age, so anything in the future reads as zero rather than
             * as nonsense.
             */
            var seconds = Math.max(0, now - since);

            value.textContent = spell(seconds);

            var minutes = seconds / 60;
            tile.classList.toggle('is-warm', minutes >= WARM_MINUTES && minutes < HOT_MINUTES);
            tile.classList.toggle('is-hot', minutes >= HOT_MINUTES);
        });
    }

    if (document.querySelector('[data-since]')) {
        tickClocks();
        setInterval(tickClocks, 1000);
    }

    /* ────────────────────────────────────────────── the action rail ── */

    function closeRails(except) {
        all('[data-tile].is-open').forEach(function (tile) {
            if (tile === except) return;

            tile.classList.remove('is-open');

            var handle = tile.querySelector('[data-tile-handle]');
            if (handle) handle.setAttribute('aria-expanded', 'false');
        });
    }

    all('[data-tile-handle]').forEach(function (handle) {
        handle.addEventListener('click', function (event) {
            event.stopPropagation();

            var tile = handle.closest('[data-tile]');
            var open = tile.classList.toggle('is-open');

            handle.setAttribute('aria-expanded', open ? 'true' : 'false');
            closeRails(tile);
        });
    });

    document.addEventListener('click', function () { closeRails(null); });

    document.addEventListener('keydown', function (event) {
        if (event.key !== 'Escape') return;

        closeRails(null);
        all('[data-modal].is-open').forEach(closeModal);
    });

    /* ───────────────────────────────────────────────── shift a table ── */

    all('[data-shift]').forEach(function (button) {
        button.addEventListener('click', function (event) {
            event.stopPropagation();

            var modal = openModal('shift');
            if (!modal) return;

            var form = modal.querySelector('[data-shift-form]');
            var name = modal.querySelector('[data-shift-name]');

            /*
             * The form is rendered once with a placeholder order id and the
             * button writes the real one in. The server checks the order
             * belongs to this branch and that the destination is free, so a
             * tampered id gets a refusal rather than somebody else's bill.
             */
            if (form) {
                form.action = form.action.replace(/\/order\/\d+\/shift$/, '/order/' + button.dataset.shift + '/shift');
            }

            if (name) name.textContent = button.dataset.shiftFrom || 'this table';
        });
    });

    /*
     * A dialog opened from the URL should still lock the page behind it, and a
     * page loaded with a hash already in it should start that way.
     */
    function syncFromHash() {
        var id = location.hash.slice(1);
        var modal = id && document.getElementById(id);

        document.body.style.overflow = modal && modal.classList.contains('nv-modal-backdrop')
            ? 'hidden'
            : '';
    }

    window.addEventListener('hashchange', syncFromHash);
    syncFromHash();

    /* ─────────────────────────────────────────────── settle and cancel ── */

    var settle = document.querySelector('[data-modal="settle"]');

    if (settle) {
        all('[data-settle-tab]', settle).forEach(function (tab) {
            tab.addEventListener('click', function (event) {
                // The href is the no-script fallback; with a script the panel
                // is switched in place and the URL is left alone.
                event.preventDefault();

                var wanted = tab.dataset.settleTab;

                all('[data-settle-tab]', settle).forEach(function (other) {
                    var on = other === tab;
                    other.classList.toggle('is-on', on);
                    other.setAttribute('aria-selected', on ? 'true' : 'false');
                });

                all('[data-settle-panel]', settle).forEach(function (panel) {
                    panel.classList.toggle('is-active', panel.dataset.settlePanel === wanted);
                });
            });
        });

        /* Say out loud what the three lines add up to, while they are typed. */
        var readout = settle.querySelector('[data-settle-sum]');
        var amounts = all('[data-settle-amount]', settle);
        var due = parseFloat(settle.getAttribute('data-due') || '0');

        if (readout && amounts.length) {
            var said = readout.textContent;

            var retotal = function () {
                var taken = amounts.reduce(function (sum, box) {
                    return sum + (parseFloat(box.value) || 0);
                }, 0);

                if (!due || Math.abs(taken - due) < 0.005) {
                    readout.textContent = said;
                    readout.classList.remove('is-short');

                    return;
                }

                var gap = due - taken;

                readout.textContent = gap > 0
                    ? '₹ ' + gap.toFixed(2) + ' short — the bill will stay open for the rest.'
                    : '₹ ' + Math.abs(gap).toFixed(2) + ' more than the bill. Only what is owed is recorded as paid.';

                readout.classList.add('is-short');
            };

            amounts.forEach(function (box) { box.addEventListener('input', retotal); });
        }

        /* An NC reason that names a department insists on one. */
        var ncType = settle.querySelector('[data-nc-type]');
        var ncDept = settle.querySelector('[data-nc-dept]');

        if (ncType && ncDept) {
            ncType.addEventListener('change', function () {
                var option = ncType.options[ncType.selectedIndex];
                var needed = option && option.dataset.needsDept === '1';

                ncDept.required = needed;

                var field = ncDept.closest('.nv-field');
                if (field) field.classList.toggle('is-required', needed);
            });
        }
    }

    /* ─────────────────────────────────────────── one-click dropdowns ── */

    all('[data-autosubmit]').forEach(function (select) {
        select.addEventListener('change', function () {
            if (select.form) select.form.submit();
        });
    });
}());
